INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (8, 0, 'Corsi di musica per adulti', 'corsi-di-musica-per-adulti', '<!-- {"type": "layout", "children": [{"type": "section", "children": []}]} --><style>.el-button{background:#e3000f;color:#fff;padding:12px 24px}</style><h1><strong>CLUSTER</strong><br />GRAPPOLO<br /><strong>GRUPPO</strong></h1><p>SCUOLA DI MUSICA CLUSTER | MILANO</p><h2>CHE SPAZIO HA LA MUSICA NELLA TUA VITA?</h2><p><a class="uk-button uk-button-primary" href="/open-day" style="background:#e3000f">PRENOTA UN OPEN DAY</a></p><h2>CORSI DI MUSICA PER ADULTI</h2><p>Dal 1999 accompagniamo gli adulti di ogni livello nello studio di uno strumento, con lezioni individuali pensate sul tuo tempo e sui tuoi obiettivi, senza esami obbligatori.</p><p>Si può cominciare in qualsiasi momento dell''anno.</p>', '', 1, 8, NOW(), 963, NOW(), NOW() - INTERVAL 0 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (9, 0, 'Corso di canto corale', 'corso-di-canto-corale', '<!-- {"type": "layout", "version": "4.5.0", "children": [{"type": "section", "children": [{"type": "row", "children": [{"type": "column", "children": [{"type": "headline", "props": {"title_element": "h1", "content": "<strong>CLUSTER</strong><br />GRAPPOLO<br /><strong>GRUPPO</strong>"}}, {"type": "button", "props": {"content": "Prenota un Open Day"}}, {"type": "text", "props": {"content": "<p>Il canto corale è il modo più semplice per cominciare a fare musica insieme: nei nostri laboratori si impara a respirare, intonare e ascoltare gli altri, senza bisogno di saper leggere la musica.</p>"}}]}]}]}]} -->', '', 1, 8, NOW(), 963, NOW(), NOW() - INTERVAL 1 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (10, 0, 'Concerto al Teatro PIME', 'concerto-teatro-pime', '<p>Sabato 11 aprile 2026 ore 18:15-20:00</p><p>Il concerto di primavera degli allievi, in scena sul palco del Teatro PIME con le classi di canto e di pianoforte.</p>', '', 1, 11, NOW(), 963, NOW(), NOW() - INTERVAL 2 MINUTE, '{}', '{}', '{}', '', 'Il concerto di primavera degli allievi di Cluster al Teatro PIME di Milano.', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (11, 0, 'Webinar sulla didattica musicale', 'webinar-didattica', '<p>Giovedì 14 maggio 2026 dalle 18 alle 19:30</p><p>Un incontro online con i docenti per capire come scegliere il primo strumento per i bambini, in diretta streaming dalla nostra sede.</p>', '', 1, 11, NOW(), 963, NOW(), NOW() - INTERVAL 3 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (12, 0, 'Saggio di fine anno', 'saggio-fine-anno', '<p>Sabato 20 giugno 2026 ore 17:00</p><p>Il saggio di fine anno degli allievi, nelle sale della scuola in via Mosè Bianchi, con ingresso libero fino a esaurimento dei posti.</p>', '', 1, 11, NOW(), 963, NOW(), NOW() - INTERVAL 4 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (13, 0, 'Serata Pop Rock', 'serata-pop-rock', '<p>Venerdì 3 luglio 2026 ore 21:00</p><p>Una serata di musica dal vivo con le band della scuola, dedicata ai grandi classici del pop e del rock.</p>', '', 1, 11, NOW(), 963, NOW(), NOW() - INTERVAL 5 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (14, 0, 'Chi siamo', 'chi-siamo', '<p>SCUOLA DI MUSICA</p><p>Siamo una scuola di musica nata a Milano nel 1999, con corsi per bambini, ragazzi e adulti.</p>', '', 1, 2, NOW(), 963, NOW(), NOW() - INTERVAL 6 MINUTE, '{}', '{}', '{}', '', 'Chi siamo: la scuola di musica Cluster di Milano, corsi per tutte le età dal 1999.', 1, '{}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (15, 0, 'Pagina riservata ai motori', 'pagina-noindex', '<p>Una pagina che il sito tiene fuori dai motori di ricerca, con abbastanza testo da sembrare una pagina vera e propria.</p>', '', 1, 2, NOW(), 963, NOW(), NOW() - INTERVAL 7 MINUTE, '{}', '{}', '{}', '', '', 1, '{"robots":"noindex, nofollow"}', '*', 1);
INSERT INTO joom_content (id, asset_id, title, alias, introtext, `fulltext`, state, catid, created, created_by, modified, publish_up, images, urls, attribs, metakey, metadesc, access, metadata, language, version) VALUES (16, 0, 'Yoga e musica', 'yoga', '<p>Una voce del glossario che sta in una categoria noindex, quindi non deve comparire in llms.txt né essere servita.</p>', '', 1, 15, NOW(), 963, NOW(), NOW() - INTERVAL 8 MINUTE, '{}', '{}', '{}', '', '', 1, '{}', '*', 1);
