-- Fixtures for AI Friendly 2.7.0 (Joomla 5.4, table prefix joom_). Run once on the test site.
DELETE FROM joom_content WHERE id >= 8;
DELETE FROM joom_categories WHERE id IN (14, 15);
DELETE FROM joom_menu WHERE id IN (201, 202, 203);
DELETE FROM joom_fields WHERE id IN (1, 2, 3);
DELETE FROM joom_fields_values WHERE field_id IN (1, 2, 3);
UPDATE joom_menu SET rgt = 53 WHERE id = 1;
UPDATE joom_categories SET rgt = 27 WHERE id = 1;
DROP TABLE IF EXISTS joom_forsef_urls;
CREATE TABLE joom_forsef_urls (id INT AUTO_INCREMENT PRIMARY KEY, sef VARCHAR(500) NOT NULL, nonsef VARCHAR(500) NOT NULL, duplicate TINYINT NOT NULL DEFAULT 0) CHARSET=utf8mb4;
DROP TABLE IF EXISTS joom_forseo_custom_meta;
CREATE TABLE joom_forseo_custom_meta (id INT AUTO_INCREMENT PRIMARY KEY, url VARCHAR(500) NOT NULL, data MEDIUMTEXT NOT NULL) CHARSET=utf8mb4;
